-- TASK-032 verification: CRA engine v2 -- policy structure, publish-time
-- validation, immutability, privileges and the app.evaluate_cra evaluator.
--
-- The 24 casebook cases below are the acceptance oracle. The jsonb literal is
-- byte-identical to apps/web/tests/fixtures/cra-casebook-v1.json (the
-- orchestrator's casebook-v1.json) -- a unit test in
-- apps/web/tests/domain/cra-engine.test.ts fails if the two ever diverge. It
-- was generated by embedding the file's exact contents between dollar-quote
-- tags (no re-serialisation); regenerate it the same way, never by hand.
-- The policy under test is the seeded CRA Template v1 DRAFT, published in the
-- "EU Payments Demo Ltd." tenant by supabase/seed.sql.
--
-- Run in a single psql session after 000-local-auth-shim.sql, all migrations
-- and supabase/seed.sql. See supabase/tests/README.md.

\set ON_ERROR_STOP on

begin;

create or replace function pg_temp.assert(p_condition boolean, p_message text)
returns void language plpgsql as $$
begin
  if not p_condition then
    raise exception 'ASSERTION FAILED: %', p_message;
  end if;
  raise notice 'ok - %', p_message;
end;
$$;

-- Runs a statement and returns 'OK' or the SQLSTATE it raised.
create or replace function pg_temp.sqlstate_of(p_sql text)
returns text language plpgsql as $$
begin
  execute p_sql;
  return 'OK';
exception when others then
  return sqlstate;
end;
$$;

-- Copies the seeded CRA policy into a new DRAFT cra_v2 version (of any
-- tenant) so a test can mutate one thing and try to publish it.
create or replace function pg_temp.copy_cra(p_tenant uuid, p_version_number int)
returns uuid language plpgsql as $$
declare
  v_new uuid := gen_random_uuid();
  v_src constant uuid := '20000000-0000-0000-0000-000000000020';
begin
  insert into public.policy_versions (id, tenant_id, version_number, status, created_by, engine_kind, label, missing_factor_points)
  select v_new, p_tenant, p_version_number, 'draft', '00000000-0000-0000-0000-000000000002', 'cra_v2', label, missing_factor_points
  from public.policy_versions where id = v_src;
  insert into public.policy_categories (tenant_id, policy_version_id, key, label, weight, position)
  select p_tenant, v_new, key, label, weight, position from public.policy_categories where policy_version_id = v_src;
  insert into public.policy_category_factors (tenant_id, policy_version_id, category_key, factor_key, weight, position, points)
  select p_tenant, v_new, category_key, factor_key, weight, position, points from public.policy_category_factors where policy_version_id = v_src;
  insert into public.policy_overrides (tenant_id, policy_version_id, code, position, fact_key, match_values, effect, actions, approvals)
  select p_tenant, v_new, code, position, fact_key, match_values, effect, actions, approvals from public.policy_overrides where policy_version_id = v_src;
  insert into public.policy_cra_bands (tenant_id, policy_version_id, band, min_score, max_score, max_inclusive, dd_level, review_months, actions, approvals)
  select p_tenant, v_new, band, min_score, max_score, max_inclusive, dd_level, review_months, actions, approvals from public.policy_cra_bands where policy_version_id = v_src;
  return v_new;
end;
$$;

-- Tries to publish; a failure is rolled back (inner block) and its SQLSTATE returned.
create or replace function pg_temp.try_publish(p_version uuid)
returns text language plpgsql as $$
begin
  update public.policy_versions
  set status = 'published', effective_from = now(), published_at = now(),
      published_by = '00000000-0000-0000-0000-000000000002'
  where id = p_version;
  return 'OK';
exception when others then
  return sqlstate;
end;
$$;

