-- 0. Structure of the seeded template ---------------------------------------
select pg_temp.assert(
  (select engine_kind = 'cra_v2' and status = 'published' and label = 'EU Payments & Gaming CRA — v1 DRAFT' and missing_factor_points = 50
   from public.policy_versions where id = '20000000-0000-0000-0000-000000000020'),
  'seed: Template v1 is a published cra_v2 version labelled "EU Payments & Gaming CRA — v1 DRAFT" in the demo tenant'
);
select pg_temp.assert(
  (select tenant_id from public.policy_versions where id = '20000000-0000-0000-0000-000000000020') = '10000000-0000-0000-0000-000000000004'
  and (select slug from public.tenants where id = '10000000-0000-0000-0000-000000000004') = 'eu-payments-demo',
  'seed: the policy lives in the new tenant EU Payments Demo Ltd. (slug eu-payments-demo)'
);
select pg_temp.assert(
  (select count(*) from public.policy_categories where policy_version_id = '20000000-0000-0000-0000-000000000020') = 5
  and (select count(*) from public.policy_category_factors where policy_version_id = '20000000-0000-0000-0000-000000000020') = 14
  and (select count(*) from public.policy_overrides where policy_version_id = '20000000-0000-0000-0000-000000000020') = 7
  and (select count(*) from public.policy_cra_bands where policy_version_id = '20000000-0000-0000-0000-000000000020') = 3,
  'seed: 5 categories, 14 factors, 7 overrides and 3 bands were loaded from the template JSON'
);
select pg_temp.assert(
  (select engine_kind from public.policy_versions where id = '20000000-0000-0000-0000-000000000010') = 'weighted_v1',
  'existing policy versions keep engine_kind weighted_v1'
);
select pg_temp.assert(
  pg_temp.sqlstate_of($q$update public.policy_versions set engine_kind = 'bogus' where id = '20000000-0000-0000-0000-000000000010'$q$) in ('23514', '23001'),
  'an unknown engine_kind is rejected'
);

-- 1. The casebook: every case must match exactly (jsonb equality of the whole object) --
select pg_temp.assert((select count(*) from cra_casebook) = 24, 'casebook has 24 cases');
do $$
declare
  v_case jsonb;
  v_got jsonb;
begin
  for v_case in select c from cra_casebook order by c ->> 'id' loop
    v_got := app.evaluate_cra('10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000020', v_case -> 'facts');
    if v_got is distinct from (v_case -> 'expected') then
      raise exception 'ASSERTION FAILED: casebook % (%) got % expected %', v_case ->> 'id', v_case ->> 'title', v_got, v_case -> 'expected';
    end if;
    raise notice 'ok - casebook % matches exactly: %', v_case ->> 'id', v_case ->> 'title';
  end loop;
end;
$$;

-- 2. Semantics beyond the casebook --------------------------------------------
do $$
declare
  v_base jsonb := (select c -> 'facts' from cra_casebook where c ->> 'id' = 'CB-01');
  v_absent jsonb;
  v_null jsonb;
  v_r jsonb;
begin
  v_absent := app.evaluate_cra('10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000020', v_base - 'purpose');
  v_null := app.evaluate_cra('10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000020', v_base || '{"purpose": null}'::jsonb);
  perform pg_temp.assert(v_absent = v_null and v_absent -> 'missing_factors' = '["purpose"]'::jsonb,
    'a JSON null fact counts as absent (same result as the key being missing)');
  perform pg_temp.assert(NOT (v_null -> 'reason_codes') ? 'INVALID_VALUE_PURPOSE',
    'a null fact is missing, not invalid');

  v_r := app.evaluate_cra('10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000020', v_base || '{"purpose": 5}'::jsonb);
  perform pg_temp.assert((v_r -> 'reason_codes') ? 'INVALID_VALUE_PURPOSE' and (v_r -> 'reason_codes') ? 'DATA_MISSING_PURPOSE',
    'a non-string value for a mapped factor is missing and invalid');
  v_r := app.evaluate_cra('10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000020', v_base || '{"purpose": true}'::jsonb);
  perform pg_temp.assert((v_r -> 'missing_factors') = '["purpose"]'::jsonb, 'a boolean value for a mapped factor is missing and invalid');

  v_r := app.evaluate_cra('10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000020', v_base || '{"sanctions_match": ["confirmed"]}'::jsonb);
  perform pg_temp.assert(v_r -> 'overrides_hit' = '[]'::jsonb, 'an array fact never hits an override (exact scalar match only)');

  v_r := app.evaluate_cra('10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000020', v_base || '{"unrelated_fact": "x"}'::jsonb);
  perform pg_temp.assert(v_r = (select c -> 'expected' from cra_casebook where c ->> 'id' = 'CB-01'), 'unknown extra facts are ignored');

  perform pg_temp.assert(
    app.evaluate_cra('10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000020', v_base)
    = app.evaluate_cra('10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000020', v_base),
    'evaluation is deterministic');
  perform pg_temp.assert(
    pg_temp.sqlstate_of($q$select app.evaluate_cra('10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000020', '[]'::jsonb)$q$) = '22023',
    'facts that are not a JSON object raise 22023');
  perform pg_temp.assert(
    (select provolatile from pg_proc where oid = 'app.evaluate_cra(uuid,uuid,jsonb)'::regprocedure) = 's'
    and (select prosecdef from pg_proc where oid = 'app.evaluate_cra(uuid,uuid,jsonb)'::regprocedure),
    'app.evaluate_cra is stable and security definer');
end;
$$;

-- 3. Publish-time validation: one negative per rule, and no partial publish ----
do $$
declare
  v_ok uuid;
  v_bad uuid;
  v_case record;
  v_n int := 100;
  v_result text;
begin
  -- Positive control: an untouched copy publishes.
  v_ok := pg_temp.copy_cra('10000000-0000-0000-0000-000000000004', 2);
  v_result := pg_temp.try_publish(v_ok);
  perform pg_temp.assert(v_result = 'OK', 'an unmodified copy of the template publishes');
  perform pg_temp.assert((select status from public.policy_versions where id = v_ok) = 'published',
    'the published copy has status published');

  for v_case in
    select * from (values
      ('category weights do not sum to 100', $m$update public.policy_categories set weight = 25 where policy_version_id = %L and key = 'customer'$m$),
      ('factor weights in a category do not sum to 100', $m$update public.policy_category_factors set weight = 35 where policy_version_id = %L and factor_key = 'purpose'$m$),
      ('a points map is empty', $m$update public.policy_category_factors set points = '{}'::jsonb where policy_version_id = %L and factor_key = 'purpose'$m$),
      ('a points value is above 100', $m$update public.policy_category_factors set points = '{"ecommerce": 0, "gambling": 150}'::jsonb where policy_version_id = %L and factor_key = 'purpose'$m$),
      ('a points value is negative', $m$update public.policy_category_factors set points = '{"ecommerce": -5}'::jsonb where policy_version_id = %L and factor_key = 'purpose'$m$),
      ('a points value is not a number', $m$update public.policy_category_factors set points = '{"ecommerce": "low"}'::jsonb where policy_version_id = %L and factor_key = 'purpose'$m$),
      ('a points map is not an object', $m$update public.policy_category_factors set points = '[0, 50]'::jsonb where policy_version_id = %L and factor_key = 'purpose'$m$),
      ('bands have a gap', $m$update public.policy_cra_bands set max_score = 30 where policy_version_id = %L and band = 'LOW'$m$),
      ('bands overlap', $m$update public.policy_cra_bands set min_score = 30 where policy_version_id = %L and band = 'MEDIUM'$m$),
      ('bands do not start at 0', $m$update public.policy_cra_bands set min_score = 5 where policy_version_id = %L and band = 'LOW'$m$),
      ('the last band is not inclusive of 100', $m$update public.policy_cra_bands set max_inclusive = false where policy_version_id = %L and band = 'HIGH'$m$),
      ('the last band does not reach 100', $m$update public.policy_cra_bands set max_score = 99 where policy_version_id = %L and band = 'HIGH'$m$),
      ('there is no HIGH band', $m$delete from public.policy_cra_bands where policy_version_id = %L and band = 'HIGH'$m$),
      ('a band lists an unknown approval', $m$update public.policy_cra_bands set approvals = '["CEO"]'::jsonb where policy_version_id = %L and band = 'HIGH'$m$),
      ('an override has an unknown effect', $m$update public.policy_overrides set effect = 'deny' where policy_version_id = %L and code = 'OVR_PEP'$m$),
      ('an override has no match values', $m$update public.policy_overrides set match_values = '[]'::jsonb where policy_version_id = %L and code = 'OVR_HNWI'$m$),
      ('an override lists actions that are not strings', $m$update public.policy_overrides set actions = '[1]'::jsonb where policy_version_id = %L and code = 'OVR_HNWI'$m$),
      ('missing_factor_points is not set', $m$update public.policy_versions set missing_factor_points = null where id = %L$m$),
      ('there are no categories', $m$delete from public.policy_categories where policy_version_id = %L$m$)
    ) as t(label, stmt)
  loop
    v_n := v_n + 1;
    v_bad := pg_temp.copy_cra('10000000-0000-0000-0000-000000000004', v_n);
    execute format(v_case.stmt, v_bad);
    perform pg_temp.assert(pg_temp.try_publish(v_bad) = '22023',
      format('publish is blocked with 22023 when %s', v_case.label));
    perform pg_temp.assert(
      (select status = 'draft' and published_at is null and published_by is null from public.policy_versions where id = v_bad),
      format('no partial publish when %s', v_case.label));
  end loop;
end;
$$;

-- 4. A published cra_v2 policy is immutable (every child, every write) ---------
do $$
declare
  v_t text;
  v_op text;
  v_sql text;
  v_p constant text := '20000000-0000-0000-0000-000000000020';
  v_d constant text := '10000000-0000-0000-0000-000000000004';
begin
  foreach v_t in array array['policy_categories', 'policy_category_factors', 'policy_overrides', 'policy_cra_bands'] loop
    foreach v_op in array array['insert', 'update', 'delete'] loop
      v_sql := case v_t || '/' || v_op
        when 'policy_categories/insert' then format($f$insert into public.policy_categories (tenant_id, policy_version_id, key, label, weight, position) values (%L, %L, 'extra', 'Extra', 1, 99)$f$, v_d, v_p)
        when 'policy_category_factors/insert' then format($f$insert into public.policy_category_factors (tenant_id, policy_version_id, category_key, factor_key, weight, position, points) values (%L, %L, 'channel', 'extra_factor', 1, 99, '{"a": 1}'::jsonb)$f$, v_d, v_p)
        when 'policy_overrides/insert' then format($f$insert into public.policy_overrides (tenant_id, policy_version_id, code, position, fact_key, match_values, effect) values (%L, %L, 'OVR_EXTRA', 99, 'x', '["y"]'::jsonb, 'reject')$f$, v_d, v_p)
        when 'policy_cra_bands/insert' then format($f$insert into public.policy_cra_bands (tenant_id, policy_version_id, band, min_score, max_score, dd_level, review_months) values (%L, %L, 'LOW', 0, 1, 'SDD', 1)$f$, v_d, v_p)
        when 'policy_categories/update' then format('update public.policy_categories set weight = 99 where policy_version_id = %L', v_p)
        when 'policy_category_factors/update' then format($f$update public.policy_category_factors set points = '{"a": 1}'::jsonb where policy_version_id = %L$f$, v_p)
        when 'policy_overrides/update' then format($f$update public.policy_overrides set effect = 'reject' where policy_version_id = %L$f$, v_p)
        when 'policy_cra_bands/update' then format('update public.policy_cra_bands set review_months = 1 where policy_version_id = %L', v_p)
        else format('delete from public.%I where policy_version_id = %L', v_t, v_p)
      end;
      perform pg_temp.assert(pg_temp.sqlstate_of(v_sql) = '23001',
        format('published policy: %s on %s is blocked (23001)', v_op, v_t));
    end loop;
  end loop;
  perform pg_temp.assert(
    pg_temp.sqlstate_of(format($f$update public.policy_versions set label = 'tampered' where id = %L$f$, v_p)) = '23001',
    'published policy: its label cannot be changed');
  perform pg_temp.assert(
    pg_temp.sqlstate_of(format($f$update public.policy_versions set status = 'archived', missing_factor_points = 0 where id = %L$f$, v_p)) = '23001',
    'published policy: archiving cannot also change missing_factor_points');
  perform pg_temp.assert(
    pg_temp.sqlstate_of(format($f$update public.policy_versions set status = 'archived', engine_kind = 'weighted_v1' where id = %L$f$, v_p)) = '23001',
    'published policy: archiving cannot also change engine_kind');
end;
$$;

-- 5. Privileges: authenticated/anon cannot evaluate or write ------------------
select pg_temp.assert(
  not has_function_privilege('authenticated', 'app.evaluate_cra(uuid,uuid,jsonb)', 'execute')
  and not has_function_privilege('anon', 'app.evaluate_cra(uuid,uuid,jsonb)', 'execute'),
  'app.evaluate_cra is not executable by authenticated or anon');
select pg_temp.assert(
  not has_function_privilege('authenticated', 'app.validate_cra_policy_on_publish()', 'execute')
  and not has_function_privilege('authenticated', 'app.cra_string_array_valid(jsonb,text[])', 'execute'),
  'the CRA validator helpers are not executable by authenticated');

insert into public.memberships (tenant_id, user_id, role_key, status) values
  ('10000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000002', 'tenant_admin', 'active'),
  ('10000000-0000-0000-0000-000000000004', '00000000-0000-0000-0000-000000000005', 'auditor', 'active');

set role authenticated; set local "request.jwt.claim.role" = 'authenticated'; set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000002';
select pg_temp.assert(
  pg_temp.sqlstate_of($q$select app.evaluate_cra('10000000-0000-0000-0000-000000000004', '20000000-0000-0000-0000-000000000020', '{}'::jsonb)$q$) = '42501',
  'tenant_admin cannot call app.evaluate_cra (42501)');
do $$
declare v_t text; v_op text; v_sql text;
begin
  foreach v_t in array array['policy_categories', 'policy_category_factors', 'policy_overrides', 'policy_cra_bands'] loop
    foreach v_op in array array['insert', 'update', 'delete'] loop
      v_sql := case v_op
        when 'insert' then format('insert into public.%I (tenant_id) values (%L)', v_t, '10000000-0000-0000-0000-000000000004')
        when 'update' then format('update public.%I set created_at = now()', v_t)
        else format('delete from public.%I', v_t)
      end;
      perform pg_temp.assert(pg_temp.sqlstate_of(v_sql) = '42501',
        format('tenant_admin (holds policy.manage) cannot %s %s: no write grant (42501)', v_op, v_t));
    end loop;
  end loop;
end;
$$;
select pg_temp.assert(
  (select count(*) from public.policy_categories where policy_version_id = '20000000-0000-0000-0000-000000000020') = 5
  and (select count(*) from public.policy_category_factors where policy_version_id = '20000000-0000-0000-0000-000000000020') = 14
  and (select count(*) from public.policy_overrides where policy_version_id = '20000000-0000-0000-0000-000000000020') = 7
  and (select count(*) from public.policy_cra_bands where policy_version_id = '20000000-0000-0000-0000-000000000020') = 3,
  'a member with policy.view (tenant_admin) reads the whole CRA structure');
reset role;

set role authenticated; set local "request.jwt.claim.role" = 'authenticated'; set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000005';
select pg_temp.assert(
  (select count(*) from public.policy_cra_bands where policy_version_id = '20000000-0000-0000-0000-000000000020') = 3,
  'auditor (policy.view) reads the CRA bands');
reset role;

set role authenticated; set local "request.jwt.claim.role" = 'authenticated'; set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000006';
select pg_temp.assert(
  (select count(*) from public.policy_categories) = 0 and (select count(*) from public.policy_category_factors) = 0
  and (select count(*) from public.policy_overrides) = 0 and (select count(*) from public.policy_cra_bands) = 0,
  'an outsider tenant admin reads nothing of another tenant''s CRA structure');
reset role;

set role authenticated; set local "request.jwt.claim.role" = 'authenticated'; set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000001';
select pg_temp.assert(
  (select count(*) from public.policy_categories) = 0 and (select count(*) from public.policy_cra_bands) = 0,
  'a platform administrator reads no tenant CRA structure (no operational bypass)');
reset role;

set role anon;
select pg_temp.assert(
  pg_temp.sqlstate_of($q$select count(*) from public.policy_categories$q$) = '42501',
  'anon has no access to the CRA child tables');
reset role;

-- 6. Cross-tenant and non-cra_v2 versions raise 22023 -------------------------
select pg_temp.assert(
  pg_temp.sqlstate_of($q$select app.evaluate_cra('10000000-0000-0000-0000-000000000003', '20000000-0000-0000-0000-000000000020', '{}'::jsonb)$q$) = '22023',
  'evaluating another tenant''s cra_v2 version raises 22023');
select pg_temp.assert(
  pg_temp.sqlstate_of($q$select app.evaluate_cra('10000000-0000-0000-0000-000000000003', '20000000-0000-0000-0000-000000000010', '{}'::jsonb)$q$) = '22023',
  'evaluating a weighted_v1 version raises 22023');
select pg_temp.assert(
  pg_temp.sqlstate_of($q$select app.evaluate_cra('10000000-0000-0000-0000-000000000004', gen_random_uuid(), '{}'::jsonb)$q$) = '22023',
  'evaluating a nonexistent version raises 22023');

-- 7. Regression: a tenant with a published cra_v2 still evaluates suppliers
-- with its weighted_v1 policy (Amendment 1) ---------------------------------
set role authenticated; set local "request.jwt.claim.role" = 'authenticated'; set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000002';
select public.create_supplier('10000000-0000-0000-0000-000000000003', 'SUP-CRA-COEXIST', 'Coexist Ltd.', 'MT', 'FICT-COEXIST', 'industrial_components', array['MT'], 'CRA coexistence fixture.', 1000, 'EUR', 'assisted', null);
reset role;

do $$
declare
  v_cra uuid := pg_temp.copy_cra('10000000-0000-0000-0000-000000000003', 50);
begin
  perform pg_temp.assert(pg_temp.try_publish(v_cra) = 'OK', 'Meridian publishes a cra_v2 version alongside its weighted_v1 policy');
  perform pg_temp.assert(
    (select count(*) from public.policy_versions where tenant_id = '10000000-0000-0000-0000-000000000003' and status = 'published' and engine_kind = 'cra_v2') = 1
    and (select count(*) from public.policy_versions where tenant_id = '10000000-0000-0000-0000-000000000003' and status = 'published' and engine_kind = 'weighted_v1') = 1
    and (select published_at from public.policy_versions where id = v_cra) > (select published_at from public.policy_versions where id = '20000000-0000-0000-0000-000000000010'),
    'the cra_v2 version is the most recently published policy of the tenant');
end;
$$;

set role authenticated; set local "request.jwt.claim.role" = 'authenticated'; set local "request.jwt.claim.sub" = '00000000-0000-0000-0000-000000000002';
do $$
declare v_result public.evaluations;
begin
  v_result := public.run_supplier_evaluation(
    '10000000-0000-0000-0000-000000000003',
    (select id from public.suppliers where reference = 'SUP-CRA-COEXIST'),
    'd1000000-0000-0000-0000-000000000001');
  perform pg_temp.assert(v_result.status = 'completed' and v_result.policy_version_id = '20000000-0000-0000-0000-000000000010',
    'supplier evaluation still uses the tenant''s weighted_v1 policy when a newer cra_v2 is published');
end;
$$;
reset role;

do $$
begin
  raise notice 'CRA engine v2 verification completed successfully.';
end;
$$;

rollback;
